        let mut pairs: Vec<String> = Vec::new();
        if let Some(value) = &self.deleted_count { pairs.push(format!("deleted_count={}", value)); }
        for value in &self.deleted_artifact_ids { pairs.push(format!("deleted_artifact_ids={}", value)); }
